-- The deployed contact is private. Supply whale_watch.sec_contact when provisioning a new project.
do $$ declare token text; contact_value text := current_setting('whale_watch.sec_contact', true); begin if contact_value is null or contact_value = '' then raise exception 'Set whale_watch.sec_contact to your SEC contact email before applying this migration'; end if; if not exists(select 1 from vault.secrets where name='whale_watch_cron_token') then token:=gen_random_uuid()::text||gen_random_uuid()::text; perform vault.create_secret(token,'whale_watch_cron_token','Whale Watch scheduled worker credential'); else select decrypted_secret into token from vault.decrypted_secrets where name='whale_watch_cron_token'; end if; insert into public.ww_worker_settings(id,contact,token_hash) values(true,contact_value,encode(extensions.digest(token,'sha256'),'hex')) on conflict(id) do update set contact=excluded.contact,token_hash=excluded.token_hash; end $$;
select whale_private.dispatch('scion');
